package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.jsoup.Connection;
import org.jsoup.Jsoup;
import org.jsoup.helper.HttpConnection;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Document;
import org.jsoup.parser.Tag;
import org.jsoup.select.Elements;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class FormElement_formData_TriageGen2Test {

    private Document doc;
    private FormElement form;

    @Before
    public void setUp() {
        doc = Document.create("");
        form = doc.createElement("form");
    }

    @Test
    public void testFormData_EmptyForm() {
        List<Connection.KeyVal> result = form.formData();
        assertTrue(result.isEmpty());
    }

    @Test
    public void testFormData_NonSubmittableElement() {
        // Assuming tag().isFormSubmittable() returns false for non-form tags like 'div'
        Element div = doc.createElement("div");
        div.attr("name", "test");
        form.appendChild(div);

        List<Connection.KeyVal> result = form.formData();
        assertTrue(result.isEmpty());
    }

    @Test
    public void testFormData_ElementWithoutName() {
        Element input = doc.createElement("input");
        input.attr("type", "text");
        // No name attribute
        form.appendChild(input);

        List<Connection.KeyVal> result = form.formData();
        assertTrue(result.isEmpty());
    }

    @Test
    public void testFormData_TextAndOtherInputs() {
        Element input = doc.createElement("input");
        input.attr("name", "username");
        input.attr("type", "text");
        input.attr("value", "john_doe");
        form.appendChild(input);

        Element password = doc.createElement("input");
        password.attr("name", "password");
        password.attr("type", "password");
        password.attr("value", "secret");
        form.appendChild(password);

        List<Connection.KeyVal> result = form.formData();
        assertEquals(2, result.size());
        assertEquals("username", result.get(0).getKey());
        assertEquals("john_doe", result.get(0).getValue());
        assertEquals("password", result.get(1).getKey());
        assertEquals("secret", result.get(1).getValue());
    }

    @Test
    public void testFormData_SelectWithSelectedOption() {
        Element select = doc.createElement("select");
        select.attr("name", "color");

        Element opt1 = doc.createElement("option");
        opt1.attr("value", "red");
        opt1.text("Red");

        Element opt2 = doc.createElement("option");
        opt2.attr("value", "blue");
        opt2.attr("selected", "selected");
        opt2.text("Blue");

        select.appendChild(opt1);
        select.appendChild(opt2);
        form.appendChild(select);

        List<Connection.KeyVal> result = form.formData();
        assertEquals(1, result.size());
        assertEquals("color", result.get(0).getKey());
        assertEquals("blue", result.get(0).getValue());
    }

    @Test
    public void testFormData_SelectWithMultipleSelectedOptions() {
        Element select = doc.createElement("select");
        select.attr("name", "colors");

        Element opt1 = doc.createElement("option");
        opt1.attr("value", "red");
        opt1.attr("selected", "selected");

        Element opt2 = doc.createElement("option");
        opt2.attr("value", "blue");
        opt2.attr("selected", "selected");

        select.appendChild(opt1);
        select.appendChild(opt2);
        form.appendChild(select);

        List<Connection.KeyVal> result = form.formData();
        assertEquals(2, result.size());
        assertEquals("red", result.get(0).getValue());
        assertEquals("blue", result.get(1).getValue());
    }

    @Test
    public void testFormData_SelectWithNoSelectedOption() {
        Element select = doc.createElement("select");
        select.attr("name", "fruit");

        Element opt1 = doc.createElement("option");
        opt1.attr("value", "apple");

        Element opt2 = doc.createElement("option");
        opt2.attr("value", "banana");

        select.appendChild(opt1);
        select.appendChild(opt2);
        form.appendChild(select);

        List<Connection.KeyVal> result = form.formData();
        assertEquals(1, result.size());
        assertEquals("fruit", result.get(0).getKey());
        assertEquals("apple", result.get(0).getValue()); // Should pick first option
    }

    @Test
    public void testFormData_SelectWithNoOptions() {
        Element select = doc.createElement("select");
        select.attr("name", "empty_select");
        form.appendChild(select);

        List<Connection.KeyVal> result = form.formData();
        assertTrue(result.isEmpty());
    }

    @Test
    public void testFormData_CheckboxChecked() {
        Element checkbox = doc.createElement("input");
        checkbox.attr("type", "checkbox");
        checkbox.attr("name", "agree");
        checkbox.attr("value", "yes");
        checkbox.attr("checked", "checked");
        form.appendChild(checkbox);

        List<Connection.KeyVal> result = form.formData();
        assertEquals(1, result.size());
        assertEquals("agree", result.get(0).getKey());
        assertEquals("yes", result.get(0).getValue());
    }

    @Test
    public void testFormData_CheckboxUnchecked() {
        Element checkbox = doc.createElement("input");
        checkbox.attr("type", "checkbox");
        checkbox.attr("name", "agree");
        checkbox.attr("value", "yes");
        form.appendChild(checkbox);

        List<Connection.KeyVal> result = form.formData();
        assertTrue(result.isEmpty());
    }

    @Test
    public void testFormData_RadioChecked() {
        Element radio = doc.createElement("input");
        radio.attr("type", "radio");
        radio.attr("name", "gender");
        radio.attr("value", "male");
        radio.attr("checked", "checked");
        form.appendChild(radio);

        List<Connection.KeyVal> result = form.formData();
        assertEquals(1, result.size());
        assertEquals("gender", result.get(0).getKey());
        assertEquals("male", result.get(0).getValue());
    }

    @Test
    public void testFormData_RadioUnchecked() {
        Element radio = doc.createElement("input");
        radio.attr("type", "radio");
        radio.attr("name", "gender");
        radio.attr("value", "male");
        form.appendChild(radio);

        List<Connection.KeyVal> result = form.formData();
        assertTrue(result.isEmpty());
    }

    @Test
    public void testFormData_CaseInsensitiveType() {
        Element checkbox = doc.createElement("input");
        checkbox.attr("type", "CHECKBOX"); // Testing case insensitivity
        checkbox.attr("name", "case_test");
        checkbox.attr("value", "val");
        checkbox.attr("checked", "checked");
        form.appendChild(checkbox);

        List<Connection.KeyVal> result = form.formData();
        assertEquals(1, result.size());
        assertEquals("case_test", result.get(0).getKey());
    }
}
